[Form]
public final class METPurchLineOpenOrder extends FormRun implements SysIFilterConsumerForm,SysIFilterEventHandler, METItemInquiryFilerProvider
{
    FormRun formRun;


}

/// <summary>
/// Initialize the filter consumer form.
/// </summary>
void init()
{
    formRun = element.args().caller() as FormRun;

    super();
    unchecked(Uncheck::XDS)
    {
        PurchLine_PurchId.enableFormRef(true);
    }

    if (METApplyWarehouseRestrictionForISPUsers())
    {
        QueryBuildDataSource qbdsUserWarehouse;
        qbdsUserWarehouse = VendPurchOpenLines_ds.queryBuildDataSource().addDataSource(tableNum(METAllowedWarehousesForISPUsers));
        qbdsUserWarehouse.joinMode(JoinMode::ExistsJoin);
        qbdsUserWarehouse.addLink(fieldnum(VendPurchOpenLines, METInventLocationId), fieldNum(METAllowedWarehousesForISPUsers, InventLocationID));
        qbdsUserWarehouse.addRange(fieldnum(METAllowedWarehousesForISPUsers, UserId)).value(curUserId());
        VendPurchOpenLines_ds.executeQuery();
    }
}

/// <summary>
/// Register the data source to which the filter should be applied.
/// </summary>
public void registerDatasourceOnQueryingEvent()
{
    VendPurchOpenLines_ds.OnQueryExecuting += eventhandler(this.parmFilterFormQueryEventHandler().applyFilter);
}

/// <summary>
/// Parameter method to get the ItemId filter from the filter form.
/// </summary>
/// <returns>ItemId</returns>
public ItemId parmItemIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(ItemId));
}

/// <summary>
/// Event handler to react on a filter change.
/// </summary>
public void onFilterChanged()
{
    VendPurchOpenLines_ds.research();
    VendPurchOpenLines_ds.executeQuery();
}

/// <summary>
/// Parameter method to get the InventLocationId filter from the filter form.
/// </summary>
/// <returns></returns>
public InventLocationId parminventoryLocationIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(InventLocationId));
}

/// <summary>
///
/// </summary>
public void executeQuery()
{
    ItemId                  itemIdFilter;
    QueryBuildDataSource    qbdsItemBarcode = this.queryBuildDataSource();
    itemIdFilter            = formRun.parmItemId();

    qbdsItemBarcode.clearRanges();

    if (itemIdFilter)
    {
        qbdsItemBarcode.addRange(fieldNum(VendPurchOpenLines, ItemId)).value(queryValue(itemIdFilter));
    }

    InventLocationId        inventLocationIdFilter;
    inventLocationIdFilter  = formRun.parminventoryLocationId();

    if (inventLocationIdFilter)
    {
        QueryBuildRange qbrInventLocation = qbdsItemBarcode.addRange(fieldNum(VendPurchOpenLines, METInventLocationId));
        qbrInventLocation.value(queryValue(inventLocationIdFilter));
        qbrInventLocation.status(RangeStatus::Locked);
    }

    super();
}

/// <summary>
///
/// </summary>
/// <param name = "_formReferenceControl"></param>
/// <returns></returns>
public Common resolveReference(FormReferenceControl _formReferenceControl)
{
    Common ret = PurchTable::find(_formReferenceControl.valueStr());

    return ret;
}

/// <summary>
///
/// </summary>
public void jumpRef()
{
    PurchTable      purchTableLoc;
    Args            args;
    MenuFunction    menuFunction;

    unchecked(Uncheck::XDS)
    {
        purchTableLoc = PurchTable::find(
        VendPurchOpenLines.PurchId
    );
    }

    if (purchTableLoc.RecId)
    {
        args = new Args();
        args.record(purchTableLoc);
        args.formViewOption(FormViewOption::Details);
        args.openMode(OpenMode::View);

        menuFunction = new MenuFunction(
        menuItemDisplayStr(PurchTableListPage),
        MenuItemType::Display
    );

        menuFunction.run(args);
    }
}
